      code: `// Divide & Conquer — O(n log n) time, O(log n) space
function majorityElement(nums) {
  function countInRange(lo, hi, target) {
    let count = 0;
    for (let i = lo; i <= hi; i++) if (nums[i] === target) count++;
    return count;
  }
  function helper(lo, hi) {
    if (lo === hi) return nums[lo];
    const mid = (lo + hi) >> 1;
    const left = helper(lo, mid);
    const right = helper(mid + 1, hi);
    if (left === right) return left;
    return countInRange(lo, hi, left) > countInRange(lo, hi, right) ? left : right;
  }
  return helper(0, nums.length - 1);
}`,
