          { action: "solve(2,5): min=2 at idx=4. area=2*4=8.", vars: { l: 2, r: 5, minIdx: 4, area: 8 }, changed: ["l","r","minIdx","area"] },
          { action: "solve(2,3): min=5 at idx=2. area=5*2=10. maxArea=10", vars: { l: 2, r: 3, area: 10, maxArea: 10 }, changed: ["area","maxArea"] },
          { action: "solve(3,3): area=6. solve(5,5): area=3. All < 10", vars: { maxArea: 10 } },
          { action: "final max=10", vars: { result: 10 }, note: "✓ Answer: 10" }
