      code: `// JS Map LRU — O(1) amortized, O(capacity) space
class LRUCache {
  constructor(capacity) {
    this.cap = capacity;
    this.map = new Map();
  }
  get(key) {
    if (!this.map.has(key)) return -1;
    const val = this.map.get(key);
    this.map.delete(key);      // remove from current position
    this.map.set(key, val);    // re-insert at end = MRU
    return val;
  }
  put(key, val) {
    if (this.map.has(key)) this.map.delete(key);
    else if (this.map.size === this.cap) {
      // evict LRU: first key in insertion order
      this.map.delete(this.map.keys().next().value);
    }
    this.map.set(key, val);    // insert at end = MRU
  }
}`,
