          { action: "dfs(2, 1)", vars: { level: 1, result: "[[1]]" }, note: "Level 1 new, push []" },
          { action: "result[1].push(2)", vars: { level: 1, result: "[[1],[2]]" }, changed: ["result"], note: "Visit node 2" },
          { action: "dfs(4, 2)", vars: { level: 2, result: "[[1],[2]]" }, note: "Level 2 new, push []" },
          { action: "result[2].push(4)", vars: { level: 2, result: "[[1],[2],[4]]" }, changed: ["result"], note: "Visit node 4" },
          { action: "dfs(5, 2) → result[2].push(5)", vars: { level: 2, result: "[[1],[2],[4,5]]" }, changed: ["result"], note: "Level 2 already exists" },
          { action: "dfs(3, 1) → result[1].push(3)", vars: { level: 1, result: "[[1],[2,3],[4,5]]" }, changed: ["result"], note: "Level 1 already exists" },
          { action: "dfs(6, 2) → result[2].push(6)", vars: { level: 2, result: "[[1],[2,3],[4,5,6]]" }, changed: ["result"], note: "✓ Answer: [[1],[2,3],[4,5,6]]" }
