        frames: [
          { action: "flatten(4): leaf → return 4 (leftTail for node 2)", vars: { node: 4, tail: 4 } },
          { action: "flatten(5): leaf → return 5 (rightTail for node 2)", vars: { node: 5, tail: 5 } },
          { action: "flatten(2): leftTail=4, rightTail=5. leftTail(4).right=2.right=5 (already). 2.right=left=4. 2.left=null", vars: { "2.right": 4, "4.right": 5, tail: 5 }, changed: ["2.right","4.right"] },
          { action: "flatten(3): leaf → return 3 (rightTail for root 1)", vars: { node: 3, tail: 3 } },
          { action: "flatten(1): leftTail=5(tail of left subtree), rightTail=3", vars: { leftTail: 5, rightTail: 3 } },
          { action: "leftTail(5).right=1.right=3. 1.right=1.left=2. 1.left=null. Return rightTail=3", vars: { "1.right": 2, "5.right": 3, "1.left": "null" }, changed: ["1.right","5.right","1.left"], note: "✓ Answer: 1→2→4→5→3" },
        ],
