      notes: "Similar in complexity to heap approach but simpler to implement without a custom heap. Requires O(n) extra space for merged arrays.",
      code: `function mergeKSortedArrays(arrays: number[][]): number[] {
  if (arrays.length === 0) return [];

  function mergeTwoSorted(a: number[], b: number[]): number[] {
    const result: number[] = [];
    let i = 0, j = 0;
    while (i < a.length && j < b.length) {
      if (a[i] <= b[j]) result.push(a[i++]);
      else result.push(b[j++]);
    }
    while (i < a.length) result.push(a[i++]);
    while (j < b.length) result.push(b[j++]);
    return result;
  }

  let current = [...arrays];
  while (current.length > 1) {
    const next: number[][] = [];
    for (let i = 0; i < current.length; i += 2) {
      if (i + 1 < current.length) {
        next.push(mergeTwoSorted(current[i], current[i + 1]));
      } else {
        next.push(current[i]);
      }
    }
    current = next;
  }

  return current[0];
}`,
