      code: `function mergeKLists(lists: Array<ListNode | null>): ListNode | null {
  const vals: number[] = [];
  for (let head of lists) {
    while (head) { vals.push(head.val); head = head.next; }
  }
  vals.sort((a, b) => a - b);
  const dummy = new ListNode(0);
  let cur = dummy;
  for (const v of vals) { cur.next = new ListNode(v); cur = cur.next!; }
  return dummy.next;
}`,
