      code: `// 2D DP — O(n*3) time, O(n*4) space
function ninjaTraining(points: number[][]): number {
  const n = points.length;
  const dp: number[][] = Array.from({ length: n }, () => [0, 0, 0, 0]);
  dp[0] = [points[0][0], points[0][1], points[0][2], 0];

  for (let day = 1; day < n; day++) {
    for (let task = 0; task < 3; task++) {
      for (let last = 0; last <= 3; last++) {
        if (last !== task) {
          dp[day][task] = Math.max(
            dp[day][task],
            points[day][task] + dp[day - 1][last]
          );
        }
      }
    }
    dp[day][3] = Math.max(dp[day][0], dp[day][1], dp[day][2]);
  }
  return dp[n - 1][3];
}`,
