      s: "O(n × 4)",
      tags: ['classic'],
      idea: "solve(day, last) = max points from day 'day' to n-1 given that task 'last' was done yesterday. Memoize on (day, last).",
      walk: [
        "Base case: day == n → return 0.",
        "Check memo[day][last].",
        "For each task (0,1,2) where task != last: try doing it today, recurse for day+1.",
        "Cache and return the max.",
      ],
      notes: "Top-down is the natural formulation. Note: in this version we go forward (day, last) rather than backward, and at day 0 last=3 (no restriction). The memo table is n×4 which is the same as the 2D DP table space.",
      code: `// Recursive Memoization — O(n*4) time/space
function ninjaTraining(points: number[][]): number {
  const n = points.length;
  const memo: number[][] = Array.from(
    { length: n }, () => new Array(4).fill(-1)
  );
  function solve(day: number, last: number): number {
    if (day === n) return 0;
    if (memo[day][last] !== -1) return memo[day][last];
    let best = 0;
    for (let task = 0; task < 3; task++) {
      if (task !== last) {
        best = Math.max(best, points[day][task] + solve(day + 1, task));
      }
    }
    return (memo[day][last] = best);
  }
  return solve(0, 3);
}`,
