      walk: [
        "Base: i == n or rem == 0 → return 0.",
        "Memo check on (i, rem).",
        "Skip item i: solve(i+1, rem).",
        "Take item i (if w[i] <= rem): v[i] + solve(i+1, rem-w[i]).",
        "Cache and return the max.",
      ],
      notes: "Top-down mirrors the subproblem naturally. The memo table is the same size as the 2D DP table. Not all subproblems may be computed (sparse access), which can be an advantage for inputs with large W but few distinct states.",
      code: `// Recursive Memoization — O(n*W) time/space
function knapsack(weights: number[], values: number[], W: number): number {
  const n = weights.length;
  const memo: number[][] = Array.from(
    { length: n }, () => new Array(W + 1).fill(-1)
  );
  function solve(i: number, rem: number): number {
    if (i === n || rem === 0) return 0;
    if (memo[i][rem] !== -1) return memo[i][rem];
    const skip = solve(i + 1, rem);
    const take = weights[i] <= rem
      ? values[i] + solve(i + 1, rem - weights[i])
      : 0;
    return (memo[i][rem] = Math.max(skip, take));
  }
  return solve(0, W);
}`,
