      code: `// Brute Force — O(2^n * n) time, O(1) space
function knapsack(weights: number[], values: number[], W: number): number {
  const n = weights.length;
  let maxVal = 0;
  for (let mask = 0; mask < (1 << n); mask++) {
    let weight = 0, value = 0;
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) {
        weight += weights[i];
        value += values[i];
      }
    }
    if (weight <= W) maxVal = Math.max(maxVal, value);
  }
  return maxVal;
}`,
