      code: `function longestCommonSubsequence(text1: string, text2: string): number {
  const memo = new Map<string, number>();
  function dp(i: number, j: number): number {
    if (i === 0 || j === 0) return 0;
    const key = i + "," + j;
    if (memo.has(key)) return memo.get(key)!;
    let res: number;
    if (text1[i - 1] === text2[j - 1]) res = dp(i - 1, j - 1) + 1;
    else res = Math.max(dp(i - 1, j), dp(i, j - 1));
    memo.set(key, res);
    return res;
  }
  return dp(text1.length, text2.length);
}`,
