          { action: "n = 8 & 7 = 1000 & 0111 = 0000 = 0, count=3", vars: { n: 0, binary: "0000", count: 3 }, changed: ["count"] },
          { action: "n=0, loop ends. Return 3", vars: { result: 3 }, note: "✓ Answer: 3" }
